<script setup lang="ts">import type {Run} from '../types/domain';import Table from './common/Table.vue';import Badge from './common/Badge.vue';import {date,dec} from '../utils/format';defineProps<{runs:Run[]}>();defineEmits<{select:[run:Run]}>()</script><template><Table :headers="['主题册 / 名称','状态','预选K / 重复','平均对齐余弦','建立时间','']"><tr v-for="r in runs" :key="r.id" :class="{contaminated:r.validity==='contaminated'}"><td><small>VOLUME / {{String(r.id).padStart(3,'0')}}</small><strong>{{r.name}}</strong><small v-if="r.supersedes_run_id">替代受污染旧版 #{{r.supersedes_run_id}} · 需重新审阅</small><small v-else-if="r.validity==='contaminated'">旧版已停止对外提供<span v-if="r.replacement_run_id"> · 替代版 #{{r.replacement_run_id}}</span></small></td><td><Badge :status="r.status" :validity="r.validity"/></td><td>{{r.config.k}} / {{r.config.repeats}}</td><td>{{r.validity==='contaminated'?'—':dec(r.result.mean_alignment_similarity)}}</td><td class="mono">{{date(r.created_at)}}</td><td><button class="text-button" @click="$emit('select',r)">{{r.validity==='contaminated'?'查看隔离记录 ↗':'阅读主题册 ↗'}}</button></td></tr></Table></template>
